/* jshint esversion: 8, node: true */
const req = msg.payload || {};
const method = String(req.method || 'POST').toUpperCase();
const endpoint = req.endpoint || '/api/v1/acct/';
const mapID = req.mapID || req.map_id || '';
const dataPayload = req.payload;
const mapClassType = (dataPayload && dataPayload.properties && dataPayload.properties.class) || '';

let uuid = '';
if (req.uuid) { uuid = '/' + req.uuid; }
else if (dataPayload && dataPayload.id) { uuid = '/' + dataPayload.id; }

const accountId = req.accountId || env.get('accountId') || env.get('CALTOPO_ACCOUNT_ID') || '';
const credentialId = req.credentialId || env.get('credentialId') || env.get('CALTOPO_CREDENTIAL_ID') || '';
const credentialKey = req.credentialKey || env.get('credentialKey') || env.get('CALTOPO_CREDENTIAL_KEY') || '';
const baseUrl = req.baseCaltopoUrl || env.get('baseCaltopoUrl') || 'https://caltopo.com';

const missing = [];
if (!accountId && endpoint === '/api/v1/acct/') missing.push('accountId');
if (!credentialId) missing.push('credentialId');
if (!credentialKey) missing.push('credentialKey');
if (missing.length) {
    msg.statusCode = 400;
    msg.caltopoError = { error: 'missing required fields: ' + missing.join(', ') };
    return [null, msg];
}

const ts = (req.since !== undefined && req.since !== null && req.since !== '') ? String(req.since) : '0';
const payloadString = (dataPayload !== undefined && dataPayload !== null) ? JSON.stringify(dataPayload) : '';
const expires = Date.now() + (2 * 60 * 1000);

let path;
if (endpoint === '/api/v1/acct/') {
    path = (method === 'POST') ? (endpoint + accountId + '/CollaborativeMap') : (endpoint + accountId + '/since/' + ts);
} else {
    path = (method === 'POST') ? (endpoint + mapID + '/' + mapClassType + uuid) : (endpoint + mapID + '/since/' + ts);
}

const signBody = (method === 'POST') ? payloadString : '';
const message = method + ' ' + path + '\n' + expires + '\n' + signBody;

const secret = Buffer.from(credentialKey, 'base64');
const signature = crypto.createHmac('sha256', secret).update(message).digest('base64');

const params = { id: credentialId, expires: expires.toString(), signature: signature };

msg.method = method;
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
if (method === 'POST') {
    params.json = payloadString;
    msg.url = baseUrl + path;
    msg.payload = querystring.stringify(params);
} else {
    msg.url = baseUrl + path + '?' + querystring.stringify(params);
    msg.payload = '';
}
return [msg, null];

let bodyObj;
let status;
if (msg.caltopoError) {
    bodyObj = msg.caltopoError;
    status = msg.statusCode || 400;
} else {
    const up = msg.payload;
    if (up && typeof up === 'object') {
        bodyObj = up;
    } else {
        try { bodyObj = JSON.parse(up); }
        catch (e) { bodyObj = { raw: (up === undefined || up === null) ? '' : String(up) }; }
    }
    status = msg.statusCode || 200;
}
msg.payload = bodyObj;
msg.statusCode = status;
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET,POST,DELETE,OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
};
return msg;
